const a={"home.about.card.list.0":"Produkta virziena pētījumi un validācija (notiek)","home.about.card.list.1":"Pamatspēju attīstība: Inženierijas sistēma / Datu un pakalpojumu spējas / Infrastruktūra","home.about.card.list.2":"Prototipēšana un ātra iterācija: no idejas līdz lietojamai versijai","home.about.card.list.3":"Atbilstība un drošība: Uzsverot datu drošību un privātuma aizsardzību","home.about.card.note":"Kā uzņēmējdarbības joma joprojām ir izpētes posmā...","home.about.card.title":"Ko mēs darām?","home.about.desc.0":"Mēs esam tīkla tehnoloģiju uzņēmums, kas koncentrējas uz pašu pētījumiem...","home.about.desc.1":"Pašreizējā biznesa joma joprojām tiek nepārtraukti izpētīta...","home.about.hl.0.num":"Pašizstrādāts pirmais","home.about.hl.0.text":"Nepārtraukta ieguldījumu veikšana savos produktos un biznesā.","home.about.hl.1.num":"Pastāvīga iterācija","home.about.hl.1.text":"Uzsvērt inženierijas kvalitāti, uzturējamību un mērogojamību.","home.about.hl.2.num":"Nepārtraukti izpētot","home.about.hl.2.text":"Dinamiskā uzņēmējdarbības virzienu attīstība pakāpeniski veido skaidras robežas.","home.about.title":"Par mums","home.brand.en":"TreeHouse Tech · Šanhaja","home.common.city":"Šanhaja · ŠANHAJA","home.common.company":"上海树下小屋网络科技有限公司","home.common.email":"house@sxxw.site","home.common.email_mailto":"mailto:house@sxxw.site","home.contact.hint":"Ja jums nepieciešams sazināties ar mums, lūdzu, sazinieties pa e-pastu...","home.contact.label.city":"Pilsēta","home.contact.label.company":"Uzņēmuma nosaukums","home.contact.label.email":"E-pasts","home.contact.title":"Saziņas informācija","home.footer.legal":"© 2025 上海树下小屋网络科技有限公司","home.footer.links.about":"Par mums","home.footer.links.contact":"Sazinieties ar mums","home.footer.links.home":"Sākumlapa","home.footer.slogan":"Fokus uz neatkarīgu pētījumu un attīstību · Nepārtraukta izpēte · Stabils iterācijas process","home.hero.cta.about":"Uzziniet vairāk par mums →","home.hero.cta.contact":"Saziņas informācija","home.hero.desc":"Mēs esam tīklu tehnoloģiju uzņēmums, kas koncentrējas uz pašu izpēti. Mēs nepārtraukti izpētām vērtīgas produktu virzienus un tehniskās īstenošanas ceļus, mērķējot uz ilgtermiņa iterāciju un stabilu piegādi.","home.hero.glass":'Virziena izpēte → Inženierijas īstenošana → Produkta pilnveidošana <span class="dot"></span> Ilgtermiņa domāšana / Stabils piegāde',"home.hero.meta.0.label":"Produkta un inženierijas fokuss","home.hero.meta.0.num":"Pašizstrādāts","home.hero.meta.1.label":"Nepārtraukta iterācija un pilnveidošana","home.hero.meta.1.num":"Ilgtermiņa","home.hero.meta.2.label":"Uzsvērt kvalitāti un atbilstību","home.hero.meta.2.num":"Stabils","home.hero.mini.foot":"* Pašreizējā oficiālā mājaslapa ir pamata ievada lapa, un saturs tiks nepārtraukti atjaunināts, attīstoties biznesam.","home.hero.mini.head":"Padoms","home.hero.mini.main":"Nepārtraukti izpētīt biznesa virzienus","home.hero.mini.stats.0.k":"Fokuss","home.hero.mini.stats.0.v":"Pašizstrādāts produkts","home.hero.mini.stats.1.k":"Forma","home.hero.mini.stats.1.v":"Pakāpeniski skaidrot","home.hero.mini.stats.2.k":"Ritms","home.hero.mini.stats.2.v":"Iteratīvs progress","home.hero.mini.stats.3.k":"Mērķis","home.hero.mini.stats.3.v":"Ilgtspējīga izaugsme","home.hero.title":'Vēršoties uz <span class="accent"> neatkarīgu pētījumu un attīstību </span> un produktu izpēti',"home.html.lang":"lv","home.meta.description":"上海树下小屋网络科技有限公司 - Vērsta uz neatkarīgu pētījumu un produktu izpēti","home.meta.title":"上海树下小屋网络科技有限公司","home.nav.about":"Par mums","home.nav.contact":"Sazinieties ar mums","home.nav.home":"Sākumlapa","home.nav.toggle":"Paplašināt izvēlni","home.noscript":"Šai vietnei ir nepieciešams JavaScript, lai nodrošinātu pilnīgu interaktīvo pieredzi (navigācijas izvēlne, ritināšanas efekti utt.).","nav.apps":"Lietotņu centrs","nav.support":"Atbalsts","apps.hero.eyebrow":"sxxw.site · Lietotņu atbalsta centrs","apps.hero.title":"Katrai lietotnei ir skaidri norādījumi un jūsu kontrolētas datu robežas.","apps.hero.desc":"Šeit atradīsiet produktu pārskatus, darba sākšanas ceļvežus, privātuma politikas, noteikumus un tehnisko atbalstu. Lasiet sadaļu par to platformu, kuru patiešām lietojat.","apps.card.cta":"Skatīt lietotni","apps.memoria.desc":"Sekojiet dzimšanas dienām, gadadienām un atpakaļskaitīšanai. iOS versija atbalsta izvēles privāto iCloud sinhronizāciju; Memoria versija Huawei AppGallery darbojas pilnībā ierīcē.","apps.memoria.tag":"Gadadienas · Atgādinājumi","apps.timetrails.desc":"Privātumu prioritizējoša GPS ierakstu žurnalēšana: automātiski reģistrē braucienus, treniņus un ceļojumus, zīmējot jūsu pēdas kartē un izgaismojot apmeklētās pilsētas. Ieraksti pēc noklusējuma paliek ierīcē ar izvēles privātu iCloud dublējumu.","apps.timetrails.tag":"GPS ieraksti · Maršruti","apps.traceapp.desc":"Reģistrē ceļu, attālumu, ātrumu un tempu. Bez konta, bez iebūvētām reklāmām vai trešo pušu analītikas.","apps.traceapp.tag":"Maršruti · Statistika","apps.footer.slogan":"Produkti · Ceļveži · Privātums un atbalsts","support.brand":"Atbalsts","support.hero.eyebrow":"sxxw.site · Atbalsta centrs","support.hero.title":"Sazinieties ar TreeHouse jums ērtākajā veidā.","support.hero.desc":"Visi oficiālie TreeHouse lietotņu atbalsta kanāli vienuviet: atsauksmes, vērtējumi lietotņu veikalos un oficiālās kopienas grupas. Vispirms ierīcē, bez reklāmām, bez trešo pušu izsekošanas.","support.g1.title":"Atsauksmes","support.g1.note":"Radās problēma vai ir ideja? Sazinieties jebkurā no zemāk minētajiem veidiem — mēs lasām katru ziņu.","support.g1.feedback.name":"Atsauksme lietotnē","support.g1.feedback.desc":"Iesniedziet tieši lietotnē; jūsu versija, ierīce un sistēmas informācija tiek pievienota automātiski, lai mēs varētu ātrāk izpētīt.","support.g1.feedback.cta":"Skatīt lietotnes","support.g1.email.name":"Sūtīt e-pastu","support.g1.email.desc":"Oficiāliem pieprasījumiem un privātuma vai konta jautājumiem e-pasts saņem izvērstāku atbildi.","support.g1.email.cta":"Sūtīt e-pastu","support.g2.title":"Novērtējiet lietotnes (katru atsevišķi)","support.g2.note":"Ja tās jums patīk, atstājiet vērtējumu izmantotajā veikalā — mēs to redzam un atbildam. Pieskarieties tai, kas atbilst jūsu lietotnei.","support.g2.cta.write":"Rakstīt atsauksmi","support.g2.cta.goto":"Doties uz vērtējumu","support.g2.memoria.huawei.platform":"HarmonyOS · Huawei ierīces","support.g3.title":"WeChat · QQ · Telegram grupas","support.g3.note":"Pievienojieties mūsu oficiālajām grupām jaunumiem un kopienas palīdzībai: WeChat / QQ Ķīnā, Telegram citviet.","support.g3.wechat.name":"WeChat grupa","support.g3.wechat.desc":"Ikdienas saziņa un palīdzība. Kad grupa piepildās, tiek publicēts jauns QR kods.","support.g3.qq.name":"QQ grupa","support.g3.qq.desc":"Lietotājiem Ķīnā; liela dalībnieku ietilpība.","support.g3.tg.name":"Telegram grupa","support.g3.tg.desc":"Saziņa un jautājumi starptautiskajiem lietotājiem.","support.g3.join":"Pievienoties","support.pending":"Drīzumā","support.foot":"Neatradāt piemēroto kanālu? Rakstiet house@sxxw.site, un mēs ar jums sazināsimies.","support.footer.slogan":"Atsauksmes · Vērtējumi veikalos · Kopienas grupas","mem.ios.tagline":"Pierakstiet dzimšanas dienas, gadadienas un svarīgas dienas — lai laiks tiek pamanīts ar maigumu.","mem.ios.desc":"Glabājiet dzimšanas dienas, gadadienas, attiecību gadadienas, svētkus un jums svarīgās dienas vienā mierīgā vietā. Skaitiet atpakaļ, cik dienu atlicis, un uz priekšu — cik jau pagājis.","mem.ios.feat.0":"Dzimšanas dienas, gadadienas, svētki un pielāgoti notikumi","mem.ios.feat.1":"Gregora un ķīniešu Mēness kalendāra datumi","mem.ios.feat.2":"Atpakaļskaitīšana, uzskaite un dzīves gaita","mem.ios.feat.3":"Vietējie atgādinājumi, sākuma un bloķēšanas ekrāna logrīki","mem.ios.feat.4":"Ātrs skats Apple Watch","mem.ios.feat.5":"Neobligāta privāta iCloud sinhronizācija","mem.ios.guide.0.t":"Izveidojiet pirmo ierakstu","mem.ios.guide.0.b":"Atverot lietotni, izvēlieties Pievienot un ievadiet nosaukumu, datumu un vēlamo piezīmi. Pēc vajadzības izvēlieties dzimšanas dienu, gadadienu, svētkus vai pielāgotu notikumu.","mem.ios.guide.1.t":"Izvēlieties datuma noteikumu","mem.ios.guide.1.b":"Dzimšanas dienām un gadadienām var izmantot Gregora vai Mēness kalendāru. Mēness kalendāra ierakstiem nākamais datums tiek aprēķināts pēc noteikuma.","mem.ios.guide.2.t":"Iestatiet atgādinājumus","mem.ios.guide.2.b":"Ieslēdziet vietējos paziņojumus svarīgām dienām un izvēlieties atgādinājuma laiku attiecīgajā dienā vai iepriekš. Ja paziņojumu atļauja ir izslēgta, lietotne aicinās atvērt sistēmas iestatījumus.","mem.ios.guide.3.t":"Ieslēdziet sinhronizāciju pēc vajadzības","mem.ios.guide.3.b":"Lai sinhronizētu starp savu iPhone, iPad un Apple Watch, ieslēdziet sinhronizāciju, esot pierakstītam iCloud. Dati nonāk jūsu privātajā CloudKit datubāzē; izstrādātāji tos nevar lasīt.","mem.hm.tagline":"Pierakstiet dzimšanas dienas, gadadienas un svarīgas dienas lokāli savā ierīcē.","mem.hm.desc":"Šī ir Memoria lokālā versija HarmonyOS platformai. Bez konta, bez tīkla, bez mākoņa sinhronizācijas; dati glabājas tikai jūsu ierīces lietotnes smilškastē.","mem.hm.feat.0":"Dzimšanas dienas, gadadienas, svētki un pielāgoti notikumi","mem.hm.feat.1":"Gregora un ķīniešu Mēness kalendāra datumi","mem.hm.feat.2":"Atpakaļskaitīšana, uzskaite un dzīves gaita","mem.hm.feat.3":"Vietējie atgādinājumi","mem.hm.feat.4":"Atjaunošana no atkritnes un pilnīga dzēšana","mem.hm.feat.5":"Bez konta, bez reklāmām, bez tīkla pieprasījumiem","mem.hm.guide.0.t":"Izveidojiet jaunu gadadienu","mem.hm.guide.0.b":"Gadadienu lapā izvēlieties Jauns un ievadiet nosaukumu, datumu, tipu un piezīmi. Vajadzības gadījumā izvēlieties Mēness kalendāra datumu.","mem.hm.guide.1.t":"Apstipriniet nākamo datumu","mem.hm.guide.1.b":"Pēc saglabāšanas lietotne pēc datuma un atkārtošanās noteikuma parāda nākamo datumu. Mēness kalendāra ieraksti tiek pārrēķināti pēc atbilstošā noteikuma.","mem.hm.guide.2.t":"Iestatiet vietējo atgādinājumu","mem.hm.guide.2.b":"Ierakstā izvēlieties atgādinājuma laiku un dienu skaitu iepriekš. Pirmoreiz iestatot atgādinājumu, atļaujiet sistēmas paziņojumus; izslēgta atļauja ietekmē tikai atgādinājumus, nevis ierakstu veidošanu vai pārlūkošanu.","mem.hm.guide.3.t":"Pārvaldiet vietējos datus","mem.hm.guide.3.b":"Dzēstie ieraksti vispirms nonāk atkritnē, un tos var atjaunot vai pilnīgi dzēst. Lietotnes atinstalēšana dzēš datus šajā ierīcē; tā kā mākoņa rezerves kopijas nav, pēc ierīces maiņas vai atinstalēšanas atjaunot tos nav iespējams.","tt.tagline":"GPS ceļu ieraksts — saglabājiet noieto ceļu savā laikā.","tt.desc":"TimeTrails ir privātumu prioritizējoša GPS ceļu ieraksta lietotne. Tā automātiski fiksē braucienu, skrējienu, riteņbraukšanas, pārgājienu un braukšanas maršrutus, spilgti parāda pēdas kartē un iedegina apmeklētās pilsētas. Bez reģistrācijas, bez reklāmām vai trešo pušu izsekošanas; ceļu dati pēc noklusējuma glabājas tikai jūsu ierīcē.","tt.feat.0":"Automātiski fiksē ikdienas kustību un nobraukumu","tt.feat.1":"Veido dienas ceļu un aktivitāšu kopsavilkumus pēc vietējā laika","tt.feat.2":"Atceries apmeklētās vietas ar miglas atklāšanu","tt.feat.3":"Atpazīst aktivitātes veidu: iešanu, riteņbraukšanu, braukšanu u.c.","tt.feat.4":"Neobligāts fotoattēlu imports, lai saglabātu maršruta atmiņas","tt.feat.5":"Neobligāta privāta iCloud datubāzes rezerves kopija un atjaunošana pēc ierīces maiņas","tt.guide.0.t":"Izvēlieties atrašanās vietas atļauju","tt.guide.0.b":"Lai ierakstīšana fonā turpinātos nepārtraukti, sistēmas uzvednē atļaujiet atrašanās vietu “Vienmēr” un “Precīza atrašanās vieta”. To jebkurā laikā varat mainīt sistēmas iestatījumos.","tt.guide.1.t":"Sāciet ierakstīšanu","tt.guide.1.b":"Pirmoreiz ienākot, ieslēdziet ierakstīšanu. Lietotnē vienmēr varat apturēt vai atsākt — kontrole ir jūsu rokās.","tt.guide.2.t":"Skatiet dienas ceļus","tt.guide.2.b":"Kalendārā vai kartē pārskatiet katras dienas maršrutu, nobraukumu, pieturas un aktivitāšu kopsavilkumu.","tt.guide.3.t":"Ieslēdziet rezerves kopiju pēc vajadzības","tt.guide.3.b":"Ja nepieciešama atjaunošana pēc ierīces maiņas vai vairāku ierīču sinhronizācija, iestatījumos pats ieslēdziet iCloud datu rezerves kopiju; pēc noklusējuma tā ir izslēgta.","trace.tagline":"Fiksējiet katru braucienu un paturiet kontroli sev.","trace.desc":"TraceApp palīdz fiksēt maršrutu, nobraukumu, ātrumu un tempu, glabājot datus vispirms ierīcē. Bez konta, bez iebūvētiem trešo pušu analītikas vai reklāmu SDK.","trace.feat.0":"Ieraksta un parāda brauciena maršrutu","trace.feat.1":"Nobraukuma, ātruma un tempa statistika","trace.feat.2":"Ceļu atskaņošana un kartes vizualizācija","trace.feat.3":"Neobligāta kustības stāvokļa atpazīšana","trace.feat.4":"Vēsture glabājas ierīces smilškastē","trace.feat.5":"Neobligāta iCloud sinhronizācija starp ierīcēm","trace.guide.0.t":"Piešķiriet atrašanās vietas atļauju","trace.guide.0.b":"Pirmoreiz lietojot, pēc vajadzības izvēlieties atrašanās vietas atļauju “Lietotnes darbības laikā” vai “Vienmēr”; atļauju jebkurā laikā var mainīt sistēmas iestatījumos.","trace.guide.1.t":"Sāciet braucienu","trace.guide.1.b":"Lietotnē sāciet ierakstīšanu — maršruts, nobraukums, ātrums un temps tiks saglabāti pašreizējā ierīcē.","trace.guide.2.t":"Atskaņojiet un sakārtojiet","trace.guide.2.b":"Vēsturē skatiet maršrutu un statistiku, dzēsiet nevajadzīgos ierakstus vai eksportējiet, izmantojot sistēmas kopīgošanu (ja lietotne to piedāvā).","trace.guide.3.t":"Ieslēdziet iCloud pēc vajadzības","trace.guide.3.b":"Lai sinhronizētu starp savām ierīcēm, pats ieslēdziet iCloud sistēmā un lietotnē; izstrādātājs neiegūst jūsu iCloud akreditācijas datus vai saturu.","app.tab.overview":"Par produktu","app.tab.start":"Darba sākšana","app.tab.privacy":"Privātuma politika","app.tab.terms":"Lietošanas noteikumi","app.tab.support":"Tehniskais atbalsts","app.cta.start":"Sākt lietot","app.cta.readPrivacy":"Lasīt privātuma politiku","app.shots":"Veikala ekrānuzņēmumi","app.faq":"Biežāk uzdotie jautājumi","app.contactTitle":"Sazinieties ar mums","app.contactQ":"Ja rodas jautājumi, rakstiet:","app.supportContact":"Vēl vajadzīga palīdzība? Rakstiet uz {email}.","app.getInStore":"Iegūstiet {app} vietnē {store}","app.legal.effective":"Spēkā stāšanās datums","app.legal.platform":"Atbalstītās platformas","app.legal.appname":"Lietotnes nosaukums","app.footerSlogan":"Par produktu · Darba sākšana · Privātums un atbalsts","tt.ui.headerSub":"GPS maršrutu ierakstīšana · Maršrutu pārskats · Vispirms privātums","tt.ui.ovTitle":"Savienojiet laiku un vietu savā stāstā","tt.ui.privTitle":"Ieraksti pieder jums, dati arī","tt.ui.privBody":"Nav vajadzīgs konts, nav reklāmu vai trešo pušu izsekošanas. Maršruti pēc noklusējuma tiek glabāti ierīcē; iCloud dublējums ir pilnīgi izvēles un nonāk tikai jūsu privātajā Apple CloudKit datubāzē.","tt.ui.guideTitle":"Sāciet ar pirmo maršrutu","tt.ui.galleryTitle":"Ieraugiet TimeTrails katras dienas maršrutā","tt.ui.desc.start":"No atrašanās vietas atļaujas līdz ikdienas maršrutu skatīšanai — sāciet ātri.","tt.ui.desc.privacy":"Uzziniet, kā šajā lietotnē tiek apstrādāta atrašanās vieta, kustība un iCloud dublējums.","tt.ui.desc.terms":"Pirms lietotnes lietošanas izlasiet lietošanas noteikumus.","tt.ui.desc.support":"Palīdz raiti ierakstīt un pārskatīt katru ceļojumu.","tt.ui.faq.0.q":"Vai TimeTrails mani izseko visu laiku?","tt.ui.faq.0.a":"Ierakstīšanu kontrolējat jūs, un to var jebkurā brīdī apturēt. Sistēmas atrašanās vieta tiek izmantota tikai maršruta ierakstīšanai ierīcē, un dati pēc noklusējuma tiek glabāti tikai ierīcē.","tt.ui.faq.1.q":"Atrašanās vieta netiek ierakstīta?","tt.ui.faq.1.a":"Sadaļā “Iestatījumi → Privātums un drošība → Atrašanās vietas pakalpojumi” lietotnei TimeTrails atlasiet “Vienmēr” un ieslēdziet “Precīza atrašanās vieta” un lietotņu darbību fonā.","tt.ui.faq.2.q":"Kā atjaunot iCloud dublējumu?","tt.ui.faq.2.a":"Ar to pašu Apple ID, ieslēgtu iCloud un normālu savienojumu varat atjaunot vai manuāli sinhronizēt iestatījumu sadaļā “iCloud datu dublējums”.","tt.ui.faq.3.q":"Kā pilnībā dzēst datus?","tt.ui.faq.3.a":"Ierīces datus varat dzēst lietotnes iestatījumos; ja ieslēgts iCloud dublējums, dzēsiet arī kopiju mākonī.","trace.ui.headerSub":"Maršrutu ierakstīšana · Pārvaldāmi dati","trace.ui.ovTitle":"Ļaujiet katram ceļam atstāt pēdas","trace.ui.privTitle":"Vispirms lokāli, dati pārvaldāmi","trace.ui.privBody":"Nav vajadzīgs konts, nav iebūvētu reklāmu vai trešo pušu statistikas. Maršruti pēc noklusējuma paliek šajā ierīcē; iCloud sinhronizācija tiek izmantota tikai tad, kad to ieslēdzat pats.","trace.ui.guideTitle":"Sāciet ar pirmo ceļu","trace.ui.galleryTitle":"Maršruti, karte un vēstures pārskats","trace.ui.desc.start":"No atrašanās vietas atļaujas līdz maršruta pārskatīšanai — sāciet ātri.","trace.ui.desc.privacy":"Uzziniet, kā tiek apstrādāti maršrutu dati, iCloud un sistēmas atļaujas.","trace.ui.desc.terms":"Pirms lietotnes lietošanas izlasiet lietošanas noteikumus.","trace.ui.desc.support":"Palīdz raiti ierakstīt un pārvaldīt katru braucienu.","trace.ui.faq.0.q":"Kā pielāgot atrašanās vietas atļaujas?","trace.ui.faq.0.a":"Sadaļā “Iestatījumi → Privātums un drošība → Atrašanās vietas pakalpojumi → TraceApp” atlasiet “Lietotnes lietošanas laikā” vai “Vienmēr”; to var jebkurā brīdī izslēgt.","trace.ui.faq.1.q":"Kā dzēst datus?","trace.ui.faq.1.a":"Lietotnē varat dzēst atsevišķu vai visus ierakstus; atinstalēšana dzēš ierīces datus. Ja ieslēgts iCloud, sinhronizēto kopiju jāpārvalda atsevišķi iCloud.","trace.ui.faq.2.q":"Kas jānorāda, ziņojot par problēmu?","trace.ui.faq.2.a":"Ieteicams pievienot atkārtošanas soļus, gaidīto un faktisko rezultātu, ierīces modeli un sistēmas versiju; var pievienot ekrānuzņēmumus, lai atvieglotu noteikšanu.","mem.ui.headerSub":"Gadadienas · Dzimšanas dienas · Atpakaļskaitīšana","mem.ui.ovTitle":"Piemērots, lai pierakstītu ikvienu svarīgo","mem.ui.privTitle":"Privātums pirms ērtības","mem.ui.priv.ios":"Nav konta, nav reklāmu, nav trešo pušu izsekošanas; ja sinhronizācija ir ieslēgta, dati nonāk tikai jūsu privātajā iCloud datubāzē.","mem.ui.priv.hm":"Nav konta, nav interneta savienojuma, nav mākoņa dublējuma; jūsu ieraksti tiek glabāti tikai šajā ierīcē.","mem.ui.guideTitle":"Sāciet ar pirmo ierakstu","mem.ui.galleryTitle":"Ieraugiet {app} īsto saskarni","mem.ui.storeHint":"Lai iegūtu šo lietotni, vietnē {store} meklējiet “{app}”.","mem.ui.desc.start":"No pirmā ieraksta izveides līdz paziņojumu atļaujai — ātri sāciet lietot {app}.","mem.ui.desc.privacy":"Izlasiet {app} privātuma politiku, kas atbilst jūsu izmantotajai platformai.","mem.ui.desc.terms":"Pirms {app} lietošanas izlasiet šos lietošanas noteikumus.","mem.ui.desc.support":"Palīdz raiti lietot {app}.","mem.ui.faq.0.q":"Vai dati tiek sinhronizēti ar citām ierīcēm?","mem.ui.faq.0.a.ios":"Pēc pieteikšanās iCloud un sinhronizācijas ieslēgšanas dati caur jūsu privāto iCloud datubāzi tiek sinhronizēti starp iPhone, iPad un Apple Watch.","mem.ui.faq.0.a.hm":"Nē. Šī versija nepieslēdzas internetam un nepiedāvā mākoņa sinhronizāciju; dati tiek glabāti tikai šajā ierīcē.","mem.ui.faq.1.q":"Kā dzēst datus?","mem.ui.faq.1.a.ios":"Ierakstus varat dzēst lietotnē; atinstalēšana dzēš lokālos datus, savukārt iCloud datus var pārvaldīt sistēmas sadaļā “Iestatījumi → iCloud”.","mem.ui.faq.1.a.hm":"Ierakstus varat dzēst lietotnē un iztukšot atkritni; atinstalēšana dzēš visus lokālos datus.","mem.ui.faq.2.q":"Ko darīt, ja atgādinājums neparādās?","mem.ui.faq.2.a":"Pārliecinieties, ka ierakstam ir iestatīts atgādinājums, un sistēmas iestatījumos atļaujiet šai lietotnei sūtīt paziņojumus. Paziņojumu izslēgšana ietekmē tikai atgādinājumus, nevis pašus ierakstus.","mem.ui.pc.title":"Saglabājiet svarīgās dienas jums piemērotā ierīcē.","mem.ui.pc.desc":"Izvēlieties izmantoto platformu. Abas versijas balstās uz lokālu datu un trešo pušu izsekošanas neesamības principu, taču atšķiras ar sinhronizācijas iespējām, lietotnes nosaukumu un piemērojamajiem noteikumiem.","mem.ui.pc.ios.desc":"Atbalsta lokālus atgādinājumus, logrīkus, Apple Watch un izvēles privātu iCloud sinhronizāciju.","mem.ui.pc.ios.cta":"Skatīt iOS versiju","mem.ui.pc.hm.desc":"Tīri lokāla versija: bez interneta savienojuma, bez mākoņa sinhronizācijas, dati paliek tikai ierīces lietotnes smilškastē.","mem.ui.pc.hm.cta":"Skatīt HarmonyOS versiju"};export{a as default};
